using SimplePZMapmaker.Core;
using SimplePZMapmaker.Web.Services;
using System.Text.Json;
using System.Net;

public static class OsmWorldTests
{
 public static IEnumerable<(string Name,Action Run)> Cases()
 {
  yield return("shared geographic projection aligns neighbouring road raster",()=>{
   var reference=new WorldGeoReference{Bounds=new(){West=30,East=30.008,South=50,North=50.002},MetresPerTile=1,OriginCellX=100,OriginCellY=100};var left=new GeographicProjection(reference,100,100);var right=new GeographicProjection(reference,101,100);var point=(30.005,50.001);Check(Math.Abs(left.Project(point).X-right.Project(point).X-256)<1e-8&&left.Project(point).Y==right.Project(point).Y,"Projection frames differ");
   var data=Road(30,50.001,30.009,50.001);var maps=new[]{left,right}.Select(projection=>{var p=MapGenerator.Generate(new(){Kind="blank"});p.WorldX=projection.CellX;p.WorldY=projection.CellY;return GeographicImporter.Import(data,p,projection.SectionBounds(256,256),default,false,projection).Project;}).ToArray();for(var y=0;y<256;y++)Check(maps[0].Terrain[y*256+255]==maps[1].Terrain[y*256],"Road seam shifted");Check(maps.All(p=>p.MetresPerTile==1&&p.Terrain.Contains(Terrain.Road)),"Common scale/road missing");
  });
  yield return("OSM preserve retains marked terrain models owners densities and spawns",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});p.Version=6;p.RequiredMods=["one"];p.AssetSources["floors_interior_tilesandwood_01_8"]="one";var index=42*256+42;p.Terrain[index]=Terrain.Water;TerrainEditMask.Mark(p,index);p.Zombies[10]=37;p.StaticModels.Add(new(){ModelId="Base.BeerBottle",ItemType="Base.BeerBottle",X=40,Y=40});p.Spawns=[new(){X=180,Y=180}];var before=JsonSerializer.Serialize(p);var source=Road(30,50,30.003,50.003);var result=GeographicImporter.Import(source,p,null,default,true).Project;Check(result.Terrain[index]==Terrain.Water&&result.TerrainEdits==p.TerrainEdits&&result.StaticModels.Count==1&&result.Zombies[10]==37&&result.Spawns[0].X==180&&result.RequiredMods.SequenceEqual(p.RequiredMods)&&result.AssetSources["floors_interior_tilesandwood_01_8"]=="one","Manual layer metadata lost");Check(JsonSerializer.Serialize(p)==before,"Import mutated original");result.StaticModels[0].X=41;Check(p.StaticModels[0].X==40,"Model copy aliases source");
   var replaced=GeographicImporter.Import(source,p,null,default,false).Project;Check(replaced.TerrainEdits==""&&replaced.StaticModels.Count==0,"Replace retained manual world layer");p.TerrainEdits="bad";Reject(()=>ProjectValidator.Validate(p));
  });
  yield return("incomplete OSM points and relation holes are omitted with warning",()=>{
   var source="""{"elements":[{"type":"way","id":1,"tags":{"highway":"path"},"geometry":[{"lon":30,"lat":50},{"lon":30.004,"lat":50.004}]},{"type":"way","id":2,"tags":{"building":"house"},"geometry":[{"lon":30.001,"lat":50.001},{},{"lon":30.002,"lat":50.002},{"lon":30.001,"lat":50.001}]},{"type":"relation","id":3,"tags":{"natural":"water"},"members":[{"type":"way","role":"outer","geometry":[{"lon":30,"lat":50},{"lon":30.004,"lat":50},{"lon":30.004,"lat":50.004},{"lon":30,"lat":50.004},{"lon":30,"lat":50}]},{"type":"way","role":"inner","geometry":[{"lon":30.001,"lat":50.001},{"lon":30.003,"lat":50.001}]}]}]}""";
   var result=GeographicImporter.Import(source,MapGenerator.Generate(new(){Kind="blank"}));Check(result.Project.Buildings.Count==0&&!result.Project.Terrain.Contains(Terrain.Water)&&result.Warnings.Any(w=>w.Contains("missing points")),"Incomplete geometry became usable contour");
  });
  yield return("tiled OSM retries deduplicates full way geometry and records cache date",()=>WithDirectory(root=>{
   var handler=new SequenceHandler([new(HttpStatusCode.GatewayTimeout),Response(Road(30,50,30.02,50.02)),Response(Road(30,50,30.02,50.02))]);using var client=new OsmClient(root,handler,TimeSpan.Zero,TimeSpan.FromSeconds(1));var reports=new List<OsmProgress>();var bounds=new GeoBounds{West=30,East=30.001,South=50,North=50.015};var result=client.FetchTiledDetailed(bounds,default,new TestProgress(reports.Add)).GetAwaiter().GetResult();using var json=JsonDocument.Parse(result.Data);Check(handler.Calls==3&&json.RootElement.GetProperty("elements").GetArrayLength()==1&&json.RootElement.GetProperty("elements")[0].GetProperty("geometry")[1].GetProperty("lat").GetDouble()==50.02,"Retry/dedup truncated full geometry");Check(result.DataTimestamp=="2026-10-13T00:00:00Z"&&reports.Any(p=>p.Warning is not null),"Source date/progress missing");var cached=client.FetchTiledDetailed(bounds,default).GetAwaiter().GetResult();Check(cached.FromCache&&cached.Requests==0&&handler.Calls==3&&cached.DataTimestamp==result.DataTimestamp,"Cache metadata missing");
  }));
  yield return("world OSM jobs return only complete sparse world and cancelled job keeps input",()=>WithDirectory(root=>{
   var assets=new GameAssetCatalog(root,Environment.GetEnvironmentVariable("PZMAP_GAME_PATH")??"");using var client=new OsmClient(Path.Combine(root,"cache"),new SequenceHandler([Response(Road(30,50.006,30.01,50))]),TimeSpan.Zero);using var service=new OsmWorldImportService(client,assets,Path.Combine(root,"jobs"));var request=new OsmWorldImportRequest(new(){West=30,East=30.01,South=50,North=50.006},SectionSize:512);var started=JsonSerializer.SerializeToElement(service.Start(request));var id=started.GetProperty("id").GetString()!;Wait(service,id);using var file=File.OpenRead(service.ResultFile(id));var world=JsonSerializer.Deserialize<WorldProject>(file,new JsonSerializerOptions{PropertyNameCaseInsensitive=true})!;Check(world.Maps.Count==4&&world.GeoReference?.MetresPerTile==1&&WorldAssembler.Validate(world).Width==1024,"World geometry frame/sections missing");
   var before=JsonSerializer.Serialize(world);using var pending=new OsmClient(Path.Combine(root,"pending"),new PendingHandler(),TimeSpan.Zero);using var cancelled=new OsmWorldImportService(pending,assets,Path.Combine(root,"cancelled"));var another=request with{ExistingWorld=world,PreserveEdits=true};var cancelId=JsonSerializer.SerializeToElement(cancelled.Start(another)).GetProperty("id").GetString()!;cancelled.Cancel(cancelId);Wait(cancelled,cancelId,"cancelled");Reject(()=>cancelled.ResultFile(cancelId));Check(JsonSerializer.Serialize(world)==before,"Cancellation changed original world");
  }));
  yield return("world OSM plan bounds memory and refuses changed frame preserve",()=>{
   Reject(()=>OsmWorldImportService.Plan(new(new(){West=30,East=30.5,South=50,North=50.001})));Reject(()=>OsmWorldImportService.Plan(new(new(){West=30,East=30.12,South=50,North=50.079},MetresPerTile:.5,SectionSize:256)));var world=new WorldProject{Maps=[new(){Project=MapGenerator.Generate(new(){Kind="blank"})}]};Reject(()=>OsmWorldImportService.Plan(new(new(){West=30,East=30.001,South=50,North=50.001},ExistingWorld:world,PreserveEdits:true)));
  });
 }
 private static void Wait(OsmWorldImportService service,string id,string expected="completed"){var timer=System.Diagnostics.Stopwatch.StartNew();while(timer.Elapsed<TimeSpan.FromSeconds(20)){var state=JsonSerializer.SerializeToElement(service.Status(id));var status=state.GetProperty("status").GetString();if(status is "completed" or "cancelled" or "failed"){Check(status==expected,"Unexpected job status: "+state);return;}Thread.Sleep(10);}throw new Exception("Job timed out");}
 private static string Road(double x0,double y0,double x1,double y1)=>JsonSerializer.Serialize(new{osm3s=new{timestamp_osm_base="2026-10-13T00:00:00Z"},elements=new[]{new{type="way",id=1,tags=new Dictionary<string,string>{{"highway","residential"}},geometry=new[]{new{lon=x0,lat=y0},new{lon=x1,lat=y1}}}}});
 private static HttpResponseMessage Response(string json)=>new(HttpStatusCode.OK){Content=new StringContent(json)};
 private sealed class SequenceHandler(HttpResponseMessage[] responses):HttpMessageHandler{public int Calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){token.ThrowIfCancellationRequested();return Task.FromResult(responses[Calls++]);}}
 private sealed class PendingHandler:HttpMessageHandler{protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){await Task.Delay(Timeout.Infinite,token);throw new InvalidOperationException();}}
 private sealed class TestProgress(Action<OsmProgress> callback):IProgress<OsmProgress>{public void Report(OsmProgress value)=>callback(value);}
 private static void WithDirectory(Action<string> test){var prefix=Path.GetFullPath(Path.Combine(Directory.GetCurrentDirectory(),"work","osm-world-tests"))+Path.DirectorySeparatorChar;var dir=prefix+Guid.NewGuid().ToString("N");Directory.CreateDirectory(dir);try{test(dir);}finally{if(!Path.GetFullPath(dir).StartsWith(prefix,StringComparison.OrdinalIgnoreCase))throw new Exception("Unsafe cleanup");Directory.Delete(dir,true);}}
 private static void Check(bool value,string error){if(!value)throw new Exception(error);}
 private static void Reject(Action action){try{action();}catch(ArgumentException){return;}throw new Exception("Invalid import accepted");}
}
